use spark_engine::arms;
#[allow(dead_code)] #[path = "../src/hybrid/weights.rs"] mod weights;
use engine_model::{plan::ModelPlan, safetensors::{Dtype, Header, Index, Limits}, shapes::*, split::{SplitPlan, SplitRequest}};
use std::{collections::BTreeMap, io::Write, os::unix::fs::FileExt};
#[allow(clippy::single_range_in_vec_init)] // a one-range Vec is intended.
#[test] fn mixed_storage_and_changed_header() {
    let mut p = ModelPlan::from_config(include_bytes!("../../model/tests/fixtures/qwen/Qwen3.6-35B-A3B-FP8.config.json")).unwrap(); for l in p.shape.layers.iter_mut().chain(&mut p.shape.draft) { if let Ffn::Experts(e) = &mut l.ffn { e.width = 256; e.storage = ExpertStorage::PerExpert; } }
    let specs = [("gate.weight", Dtype::F8E4M3, vec![256,2048], Store::Weight, Part::Expert { id: Some(0), proj: Proj::Gate }), ("gate.weight_scale_inv", Dtype::Bf16, vec![2,16], Store::BlockScale, Part::Expert { id: Some(0), proj: Proj::Gate }), ("linear", Dtype::Bf16, vec![8,16], Store::Weight, Part::Whole), ("state", Dtype::F32, vec![128], Store::Weight, Part::Whole), ("vision", Dtype::Bf16, vec![17], Store::Weight, Part::Whole)];
    let mut end = 0u64; let mut records = Vec::new(); p.shape.tensors = specs.iter().map(|(n,d,s,store,part)| { let start = end; end += s.iter().product::<u64>() * d.bytes(); records.push(format!("{n:?}:{{\"dtype\":{:?},\"shape\":{s:?},\"data_offsets\":[{start},{end}]}}", match d { Dtype::Bf16=>"BF16",Dtype::F32=>"F32",_=>"F8_E4M3" })); TensorEntry { name: n.to_string(), dtype:*d, shape:s.clone(), role:Role { place:if *n=="vision" { Place::Unused } else { Place::Layer(0) }, part:*part, store:*store } } }).collect();
    let root = std::env::temp_dir().join(format!("typed-weights-{}", std::process::id())); std::fs::create_dir(&root).unwrap(); let header = format!("{{\"__metadata__\":{{\"receipt\":\"a\"}},{} }}",records.join(",")); let path = root.join("tiny.safetensors"); let mut f = std::fs::File::create(&path).unwrap(); f.write_all(&(header.len() as u64).to_le_bytes()).unwrap(); f.write_all(header.as_bytes()).unwrap(); f.write_all(&vec![0x5a;end as usize]).unwrap();
    let index = Index::parse(format!("{{\"metadata\":{{\"total_size\":{end}}},\"weight_map\":{{{}}}}}",specs.iter().map(|(n,..)|format!("{n:?}:\"tiny.safetensors\"")).collect::<Vec<_>>().join(",")).as_bytes(),Limits::default()).unwrap(); let headers = BTreeMap::from([("tiny.safetensors".into(),Header::open(&path,Limits::default()).unwrap())]); let q = SplitRequest { ranks:1,memory:vec![u64::MAX],reserve:vec![0],context:1,sequences:1,cache_bytes:2,state_bytes:4,draft:false,expert_rows:false }; let split = SplitPlan::new(&p.shape,&q).unwrap(); let load = weights::LoadPlan::new(&p,&index,&headers,&split).unwrap();
    assert_eq!(load.payload_bytes(),256*2048+64+256+512); assert_eq!(load.tensors().len(),4); assert_eq!(load.tensors()["state"].bytes,512); assert!(load.bytes()<load.payload_bytes()+4*16); let opened = load.open(&root).unwrap(); for v in load.tensors().values() { assert_eq!(v.offset%16,0); let mut raw=vec![0;v.bytes]; opened[0].file().read_exact_at(&mut raw,v.file_offset).unwrap(); assert!(raw.iter().all(|b|*b==0x5a)); }
    let q2 = SplitRequest { ranks:2, memory:vec![u64::MAX;2], reserve:vec![0;2], ..q.clone() }; let tp = SplitPlan::new(&p.shape,&q2).unwrap();
    for rank in 0..2 { let local=weights::LoadPlan::for_rank(&p,&index,&headers,&tp,rank).unwrap(); let v=&local.tensors()["gate.weight"]; assert_eq!((v.rows,v.cols,v.bytes),(128,2048,128*2048)); assert_eq!(v.selection,engine_model::split::Selection::Rows(vec![u64::from(rank)*128..u64::from(rank+1)*128])); assert_eq!(local.payload_bytes() as u64,tp.ledgers[rank as usize].weights); assert_eq!(local.tensors()["gate.weight_scale_inv"].rows,1); }
    assert!(weights::LoadPlan::for_rank(&p,&index,&headers,&tp,2).is_err()); assert!(weights::LoadPlan::new(&p,&index,&headers,&tp).is_err());
    let at=8+header.find("\"a\"").unwrap()+1; f.write_all_at(b"b",at as u64).unwrap(); assert!(load.open(&root).err().unwrap().contains("changed")); drop(load); p.shape.tensors.retain(|t|t.role.store!=Store::BlockScale); assert!(weights::LoadPlan::new(&p,&index,&headers,&split).is_err());
    std::fs::remove_file(path).unwrap(); std::fs::remove_dir(root).unwrap();
}
